contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We test that when the owner (this contract) calls withdraw with value 0,
    // the call cannot change depositsCount, and if it succeeds it does not change C's balance
    // (i.e., withdrawing 0 is a no-op on depositsCount and balance).
    function run(uint dummy) public payable {
        require(true);
        // read before-values
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        // perform the state-changing call as a top-level statement: owner calling withdraw(0)
        bool reverted;
        c.withdraw(0); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read after-values
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;

        // General rule: withdraw(0) must not change depositsCount; if it succeeds it must not change balance either.
        assert(afterCount == beforeCount && (reverted || afterBal == beforeBal));
    }

    // allow receiving Ether (so this contract can be owner and receive withdrawals)
    receive() external payable {}
}

